head.b:skin:
/* ============================================================
   CSS Custom Properties — Newspaper Theme
   ============================================================ */
:root {
  --color-bg:          #FDFAF4;
  --color-paper:       #FDFAF4;
  --color-ink:         #1a1a1a;
  --color-mid:         #444444;
  --color-muted:       #888888;
  --color-rule:        #1a1a1a;
  --color-border:      #d0ccc0;
  --color-accent:      #C41230;
  --color-accent-dk:   #9c0e26;
  --color-footer-bg:   #1a1a2e;
  --color-white:       #ffffff;

  --font-masthead:     'Playfair Display', Georgia, serif;
  --font-headline:     'Playfair Display', Georgia, serif;
  --font-body:         'Libre Baskerville', Georgia, serif;
  --font-nav:          'Oswald', sans-serif;

  --content-width:     1200px;
  --sidebar-width:     280px;
  --gap:               24px;
  --transition:        0.18s ease;
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  background: var(--color-bg);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
ul, ol { list-style: none; }

/* ============================================================
   Utility
   ============================================================ */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap;
}

.container {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 16px;
}

/* ============================================================
   Masthead
   ============================================================ */
#masthead {
  display: grid;
  place-items: center;
  text-align: center;
  padding: 32px 16px 20px;
  background: var(--color-paper);
}

.masthead-rule-top {
  width: 100%;
  border: none;
  border-top: 4px solid var(--color-rule);
  margin-bottom: 18px;
}

.masthead-inner {
  display: grid;
  place-items: center;
}

.masthead-title a {
  font-family: var(--font-masthead);
  font-weight: 900;
  font-style: italic;
  font-size: clamp(2.4rem, 7vw, 5rem);
  color: var(--color-ink);
  letter-spacing: -0.01em;
  line-height: 1.05;
  text-decoration: none;
  display: block;
}

.masthead-title a:hover { color: var(--color-accent); }

.masthead-meta {
  margin-top: 8px;
  font-family: var(--font-nav);
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-mid);
  display: flex;
  align-items: center;
  gap: 12px;
}

.masthead-meta-sep { color: var(--color-accent); }

.masthead-tagline {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-top: 4px;
}

.masthead-rule-bottom {
  width: 100%;
  border: none;
  border-top: 1px solid var(--color-rule);
  margin-top: 18px;
}

/* ============================================================
   Navigation
   ============================================================ */
#navbar-outer {
  background: var(--color-ink);
  position: sticky;
  top: 0;
  z-index: 100;
}

#navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 0 16px;
  height: 44px;
}

.navbar-links {
  display: flex;
  align-items: center;
  gap: 0;
}

.navbar-links a {
  font-family: var(--font-nav);
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #ccc;
  padding: 0 14px;
  height: 44px;
  display: flex;
  align-items: center;
  border-bottom: 3px solid transparent;
  transition: color var(--transition), border-color var(--transition);
}

.navbar-links a:hover,
.navbar-links a.active {
  color: var(--color-white);
  border-bottom-color: var(--color-accent);
}

.navbar-search {
  display: flex;
  align-items: center;
  gap: 6px;
}

.navbar-search input {
  background: #333;
  border: 1px solid #555;
  color: #eee;
  font-family: var(--font-nav);
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  padding: 4px 10px;
  width: 160px;
  outline: none;
  transition: border-color var(--transition);
}

.navbar-search input:focus { border-color: var(--color-accent); }

.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-direction: column;
  gap: 5px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: #ccc;
  transition: transform var(--transition), opacity var(--transition);
}

.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ============================================================
   Page Wrapper
   ============================================================ */
#outer-wrapper {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: 28px 16px 40px;
}

/* ============================================================
   Section Divider (thick horizontal rule)
   ============================================================ */
.section-rule {
  border: none;
  border-top: 3px double var(--color-rule);
  margin: 28px 0 20px;
}

.section-heading {
  font-family: var(--font-nav);
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 16px;
}

/* ============================================================
   Index Layout — 3-column grid + sidebar
   ============================================================ */
.blog-layout {
  display: grid;
  grid-template-columns: 1fr var(--sidebar-width);
  gap: var(--gap);
  align-items: start;
}

.blog-posts-col { min-width: 0; }

.posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gap);
}

/* Column rules between grid cells */
.posts-grid {
  column-gap: var(--gap);
  position: relative;
}

/* ============================================================
   Post Card (index)
   ============================================================ */
.post-card {
  border: 1px solid var(--color-border);
  padding: 16px;
  background: var(--color-paper);
  transition: border-left-color var(--transition), border-left-width var(--transition);
  border-left: 1px solid var(--color-border);
}

.post-card:hover {
  border-left: 3px solid var(--color-accent);
}

.post-card-thumb {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  display: block;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--color-border);
}

.post-card-label {
  font-family: var(--font-nav);
  font-size: 0.62rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 6px;
}

.post-card-title {
  font-family: var(--font-headline);
  font-weight: 700;
  font-size: 1.1rem;
  line-height: 1.3;
  margin-bottom: 8px;
}

.post-card-title a {
  color: var(--color-ink);
  text-decoration: none;
  transition: color var(--transition);
}

.post-card-title a:hover { color: var(--color-accent); }

.post-card-meta {
  font-family: var(--font-nav);
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  color: var(--color-muted);
  text-transform: uppercase;
  margin-bottom: 10px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.post-card-snippet {
  font-size: 0.85rem;
  line-height: 1.65;
  color: var(--color-mid);
  text-align: justify;
  margin-bottom: 12px;
}

.read-more {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
  transition: color var(--transition);
}

.read-more:hover { color: var(--color-accent-dk); }

/* ============================================================
   Single Post Layout
   ============================================================ */
.single-layout {
  display: grid;
  grid-template-columns: 1fr var(--sidebar-width);
  gap: var(--gap);
  align-items: start;
}

.post-body-col { min-width: 0; }

.post-article {
  background: var(--color-paper);
  border: 1px solid var(--color-border);
  padding: 32px 36px;
}

.post-header { margin-bottom: 24px; }

.post-label-link {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 10px;
  display: block;
}

.post-title {
  font-family: var(--font-headline);
  font-weight: 700;
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  line-height: 1.2;
  color: var(--color-ink);
  margin-bottom: 14px;
}

.post-meta {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-muted);
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding: 8px 0;
  margin-bottom: 24px;
}

.post-meta a { color: var(--color-muted); }
.post-meta a:hover { color: var(--color-accent); }

/* Drop cap on first paragraph in single post */
.single-post-body .post-body p:first-of-type::first-letter {
  font-family: var(--font-masthead);
  font-weight: 900;
  font-size: 4.2rem;
  line-height: 0.8;
  float: left;
  margin: 4px 8px 0 0;
  color: var(--color-ink);
}

.post-body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.8;
  color: var(--color-ink);
  text-align: justify;
}

.post-body p { margin-bottom: 1.2em; }
.post-body h2, .post-body h3, .post-body h4 {
  font-family: var(--font-headline);
  font-weight: 700;
  color: var(--color-ink);
  margin: 1.6em 0 0.6em;
  line-height: 1.25;
}
.post-body h2 { font-size: 1.5rem; }
.post-body h3 { font-size: 1.2rem; }
.post-body h4 { font-size: 1rem; }

.post-body blockquote {
  border-left: 3px solid var(--color-accent);
  padding: 8px 20px;
  margin: 1.4em 0;
  font-style: italic;
  color: var(--color-mid);
}

.post-body a {
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.post-body img {
  max-width: 100%;
  height: auto;
  margin: 1em auto;
  display: block;
  border: 1px solid var(--color-border);
}

.post-body pre {
  background: #f0ede4;
  border: 1px solid var(--color-border);
  padding: 14px 16px;
  overflow-x: auto;
  font-size: 0.85rem;
  margin: 1.2em 0;
}

.post-body ul, .post-body ol {
  list-style: disc;
  padding-left: 1.6em;
  margin-bottom: 1.2em;
}

.post-body ol { list-style: decimal; }

.post-footer {
  margin-top: 28px;
  padding-top: 16px;
  border-top: 2px solid var(--color-rule);
}

.post-labels {
  margin-bottom: 12px;
  font-family: var(--font-nav);
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.post-labels a {
  color: var(--color-accent);
  margin-right: 8px;
}

.post-labels a:hover { text-decoration: underline; }

/* ============================================================
   Share Bar
   ============================================================ */
.share-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin: 20px 0 8px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border);
}

.share-label {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-right: 4px;
}

.share-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  color: #fff !important;
  text-decoration: none !important;
  border: none;
  cursor: pointer;
  transition: filter var(--transition), transform var(--transition);
  font-family: var(--font-nav);
  line-height: 1;
}

.share-btn:hover {
  filter: brightness(0.82);
  transform: translateY(-2px);
}

.share-btn.twitter  { background: #000000; }
.share-btn.facebook { background: #1877F2; }
.share-btn.whatsapp { background: #25D366; }
.share-btn.telegram { background: #0088CC; }
.share-btn.linkedin { background: #0077B5; }
.share-btn.reddit     { background: #FF4500; }
.share-btn.instagram  { background: #E1306C; }
.share-btn.email      { background: #555555; }
.share-btn.share-print { background: #444444; }

/* Instagram copied tooltip */
.share-btn.instagram.copied::after {
  content: 'Copied!';
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  background: #1a1a1a;
  color: #fff;
  font-family: 'Oswald', sans-serif;
  font-size: 10px;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 3px 8px;
  white-space: nowrap;
  pointer-events: none;
}
.share-btn.instagram { position: relative; }

/* ============================================================
   Pagination
   ============================================================ */
.blog-pager, #blog-pager {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  padding: 28px 0 8px;
}

.blog-pager a, .blog-pager span, #blog-pager a, #blog-pager span {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 1px solid var(--color-border);
  padding: 6px 14px;
  color: var(--color-mid);
  transition: border-color var(--transition), color var(--transition);
}

.blog-pager a:hover, #blog-pager a:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.blog-pager .current, #blog-pager .current {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

/* ============================================================
   Sidebar
   ============================================================ */
#sidebar-wrapper {
  min-width: 0;
}

.sidebar-section {
  margin-bottom: 28px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--color-border);
}

.sidebar-section:last-child { border-bottom: none; }

.sidebar-heading {
  font-family: var(--font-nav);
  font-size: 0.68rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-ink);
  padding-top: 10px;
  border-top: 2px solid var(--color-accent);
  margin-bottom: 14px;
}

.sidebar-widget { font-size: 0.88rem; }

.sidebar-widget ul li {
  padding: 5px 0;
  border-bottom: 1px solid var(--color-border);
}

.sidebar-widget ul li:last-child { border-bottom: none; }

.sidebar-widget a { color: var(--color-mid); transition: color var(--transition); }
.sidebar-widget a:hover { color: var(--color-accent); }

/* ============================================================
   Comments
   ============================================================ */
#comments-wrapper {
  margin-top: 36px;
  padding-top: 20px;
  border-top: 3px double var(--color-rule);
}

.comments-heading {
  font-family: var(--font-headline);
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--color-ink);
  margin-bottom: 20px;
}

.comment-block {
  border-bottom: 1px solid var(--color-border);
  padding: 16px 0;
}

.comment-block:last-child { border-bottom: none; }

.comment-author {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-muted);
  margin-bottom: 6px;
}

.comment-body {
  font-size: 0.92rem;
  color: var(--color-mid);
  line-height: 1.7;
}

.comment-form-wrapper {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--color-border);
}

.comment-form-wrapper h4 {
  font-family: var(--font-nav);
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink);
  margin-bottom: 14px;
}

/* ============================================================
   Footer
   ============================================================ */
#footer-wrapper {
  background: var(--color-footer-bg);
  border-top: 4px solid var(--color-accent);
  color: #bbb;
  padding: 48px 16px 24px;
}

.footer-inner {
  max-width: var(--content-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  margin-bottom: 32px;
}

.footer-col-heading {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-white);
  border-bottom: 1px solid #444;
  padding-bottom: 8px;
  margin-bottom: 12px;
}

.footer-col { font-size: 0.82rem; line-height: 1.7; }
.footer-col a { color: #bbb; transition: color var(--transition); }
.footer-col a:hover { color: var(--color-accent); }
.footer-col ul li { padding: 3px 0; }

.footer-bottom {
  max-width: var(--content-width);
  margin: 0 auto;
  border-top: 1px solid #333;
  padding-top: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-nav);
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #666;
  flex-wrap: wrap;
  gap: 8px;
}

/* ============================================================
   Status / Alert Messages
   ============================================================ */
.status-msg-wrap {
  background: #fff8e1;
  border: 1px solid #ffe082;
  padding: 12px 16px;
  margin-bottom: 16px;
  font-size: 0.9rem;
  color: #555;
}

/* ============================================================
   Quick Edit / Admin
   ============================================================ */
.post-quick-edit-btn, .item-control {
  opacity: 0.5;
  transition: opacity var(--transition);
}

.post-quick-edit-btn:hover, .item-control:hover { opacity: 1; }

/* ============================================================
   Feed Links
   ============================================================ */
.blog-feeds, .feed-links {
  font-family: var(--font-nav);
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-muted);
  padding: 6px 0;
}

.blog-feeds a, .feed-links a { color: var(--color-accent); }

/* ============================================================
   Responsive — Tablet
   ============================================================ */
@media (max-width: 1024px) {
  :root { --sidebar-width: 240px; }
  .posts-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
}

/* ============================================================
   Responsive — Mobile
   ============================================================ */
@media (max-width: 700px) {
  .blog-layout { grid-template-columns: 1fr; }
  .single-layout { grid-template-columns: 1fr; }
  .posts-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
  #sidebar-wrapper { display: none; }

  .hamburger { display: flex; }
  .navbar-links {
    display: none;
    position: fixed;
    top: 44px;
    left: 0;
    right: 0;
    background: var(--color-ink);
    flex-direction: column;
    align-items: stretch;
    padding: 8px 0;
    z-index: 99;
  }
  .navbar-links.open { display: flex; }
  .navbar-links a {
    height: auto;
    padding: 12px 20px;
    border-bottom: none;
    border-left: 3px solid transparent;
  }
  .navbar-links a:hover,
  .navbar-links a.active {
    border-left-color: var(--color-accent);
    border-bottom: none;
  }
  .navbar-search { display: none; }

  .post-article { padding: 20px 16px; }
}

/* ============================================================
   Print
   ============================================================ */
@media print {
  #navbar-outer, #footer-wrapper, .share-bar, .blog-pager,
  #sidebar-wrapper { display: none !important; }
  body { background: #fff; color: #000; }
  .post-article { border: none; padding: 0; }
}

