body.script:
// @license magnet:?xt=urn:btih:d3d9a9a6595521f9666a5e94cc830dab83b65699&dn=expat.txt MIT

/* ---- Footer year ---- */
(function() {
  var el = document.getElementById('footer-year');
  if (el) el.textContent = new Date().getFullYear();
})();

/* ---- Masthead date ---- */
(function() {
  var el = document.getElementById('masthead-date');
  if (!el) return;
  var now = new Date();
  var opts = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
  try { el.textContent = now.toLocaleDateString(undefined, opts); } catch(e) {}
})();

/* ---- Mobile hamburger nav ---- */
(function() {
  var btn   = document.getElementById('hamburger');
  var links = document.getElementById('navbar-links');
  if (!btn || !links) return;
  btn.addEventListener('click', function() {
    var open = links.classList.toggle('open');
    btn.classList.toggle('open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
  document.addEventListener('click', function(e) {
    if (!btn.contains(e.target) && !links.contains(e.target)) {
      links.classList.remove('open');
      btn.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
    }
  });
})();

/* ---- Active nav link ---- */
(function() {
  var cur = window.location.href;
  document.querySelectorAll('#navbar-links a').forEach(function(a) {
    if (a.href && cur.indexOf(a.href) === 0) a.classList.add('active');
  });
})();

/* ---- Avatar SVG placeholder fallback ---- */
(function() {
  document.querySelectorAll('img[alt="Profile"]').forEach(function(img) {
    img.addEventListener('error', function() {
      var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.setAttribute('width', '44'); svg.setAttribute('height', '44');
      svg.setAttribute('viewBox', '0 0 44 44');
      svg.style.cssText = 'border-radius:50%;border:2px solid var(--color-accent);';
      svg.innerHTML =
        '' +
        '' +
        '';
      img.parentNode.replaceChild(svg, img);
    });
  });
})();

/* ---- createSummaryAndThumb — index post excerpts ---- */
(function() {
  var SNIPPET_LEN = 200;
  document.querySelectorAll('.post-card').forEach(function(card) {
    /* Thumbnail */
    var thumb = card.querySelector('.post-card-thumb');
    if (!thumb) {
      var body = card.querySelector('.post-card-snippet');
      if (body) {
        var imgs = body.querySelectorAll('img');
        if (imgs.length) {
          var img = imgs[0].cloneNode();
          img.className = 'post-card-thumb';
          img.removeAttribute('width'); img.removeAttribute('height');
          card.insertBefore(img, card.firstChild);
          imgs[0].parentNode.removeChild(imgs[0]);
        }
      }
    }
    /* Snippet text */
    var snip = card.querySelector('.post-card-snippet');
    if (snip) {
      var text = snip.textContent || snip.innerText || '';
      text = text.replace(/\s+/g, ' ').trim();
      if (text.length > SNIPPET_LEN) {
        snip.textContent = text.substring(0, SNIPPET_LEN).replace(/\s\S*$/, '') + '…';
      }
    }
  });
})();

/* ---- Share bar ---- */
document.querySelectorAll('.share-bar').forEach(function(bar) {
  var url   = encodeURIComponent(bar.dataset.url   || window.location.href);
  var title = encodeURIComponent(bar.dataset.title || document.title);
  var links = {
    'twitter':  'https://twitter.com/intent/tweet?url='   + url + '&text=' + title,
    'facebook': 'https://www.facebook.com/sharer/sharer.php?u=' + url,
    'whatsapp': 'https://wa.me/?text=' + title + '%20' + url,
    'telegram': 'https://t.me/share/url?url=' + url + '&text=' + title,
    'linkedin': 'https://www.linkedin.com/sharing/share-offsite/?url=' + url,
    'reddit':   'https://reddit.com/submit?url=' + url + '&title=' + title,
    'email':    'mailto:?subject=' + title + '&body=' + url,
  };
  bar.querySelectorAll('a[data-share]').forEach(function(a) {
    var key = a.dataset.share;
    if (links[key]) a.href = links[key];
    if (key !== 'email') a.target = '_blank';
  });

  /* Instagram — Web Share API on mobile, clipboard fallback on desktop */
  var igBtn = bar.querySelector('[data-share="instagram"]');
  if (igBtn) {
    igBtn.addEventListener('click', function() {
      var rawUrl   = bar.dataset.url   || window.location.href;
      var rawTitle = bar.dataset.title || document.title;
      if (navigator.share) {
        navigator.share({ title: rawTitle, url: rawUrl }).catch(function() {});
      } else {
        navigator.clipboard.writeText(rawUrl).then(function() {
          igBtn.classList.add('copied');
          setTimeout(function() { igBtn.classList.remove('copied'); }, 2000);
        }).catch(function() {
          prompt('Copy this link to share on Instagram:', rawUrl);
        });
      }
    });
  }

  var printBtn = bar.querySelector('.share-print');
  if (printBtn) {
    printBtn.addEventListener('click', function() { window.print(); });
  }
});

